"use client";

import * as React from "react";
import { cn } from "./utils";
import { Switch as SwitchPrimitive } from "./primitive-switch";

function Switch({
  className,
  size = "default",
  ...props
}: React.ComponentProps<typeof SwitchPrimitive.Root> & {
  size?: "sm" | "default";
}) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      data-size={size}
      className={cn("roc-ui", className)}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn("roc-ui")}
      />
    </SwitchPrimitive.Root>
  );
}

export { Switch };

import "./switch.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

"use client";
// ROC primitive: an on/off switch with native form participation.
import * as React from "react";
import { FormInput } from "./primitive-form-input";
import { composeEventHandlers, useComposedRefs } from "./primitive-utils";
import { useControllableState } from "./use-controllable-state";

const Context = React.createContext({ checked: false, disabled: false });

type RootProps = Omit<
  React.ComponentProps<"button">,
  "value" | "defaultChecked" | "checked"
> & {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  required?: boolean;
  name?: string;
  form?: string;
  value?: string | number | readonly string[];
};

function Root({
  checked: checkedProp,
  defaultChecked,
  onCheckedChange,
  required,
  disabled,
  name,
  form,
  value = "on",
  onClick,
  ref,
  ...props
}: RootProps) {
  const [button, setButton] = React.useState<HTMLButtonElement | null>(null);
  const composed = useComposedRefs<HTMLButtonElement>(ref, setButton);
  const stopped = React.useRef(false);
  const inForm = button ? !!form || !!button.closest("form") : true;
  const [checked, setChecked] = useControllableState(
    checkedProp,
    defaultChecked ?? false,
    onCheckedChange,
  );
  const initial = React.useRef(checked);
  // Subscribe once per form and read the latest setter: a listener re-added
  // mid-dispatch is skipped, which would drop this control from a reset.
  const latest = React.useRef(setChecked);
  latest.current = setChecked;
  React.useEffect(() => {
    const owner = button?.form;
    if (!owner) return;
    const reset = () => latest.current(initial.current);
    owner.addEventListener("reset", reset);
    return () => owner.removeEventListener("reset", reset);
  }, [button]);
  return (
    <Context.Provider value={{ checked, disabled: !!disabled }}>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-required={required}
        data-state={checked ? "checked" : "unchecked"}
        data-disabled={disabled ? "" : undefined}
        disabled={disabled}
        value={value}
        {...props}
        ref={composed}
        onClick={composeEventHandlers(onClick, (event) => {
          setChecked(!checked);
          if (inForm) {
            stopped.current = event.isPropagationStopped();
            if (!stopped.current) event.stopPropagation();
          }
        })}
      />
      {inForm && (
        <FormInput
          checked={checked}
          bubbles={!stopped.current}
          name={name}
          value={value}
          required={required}
          disabled={disabled}
          form={form}
        />
      )}
    </Context.Provider>
  );
}

function Thumb(props: React.ComponentProps<"span">) {
  const { checked, disabled } = React.useContext(Context);
  return (
    <span
      data-state={checked ? "checked" : "unchecked"}
      data-disabled={disabled ? "" : undefined}
      {...props}
    />
  );
}

export const Switch = { Root, Thumb };

"use client";
// ROC primitive: the hidden native checkbox that lets a custom control join a <form>.
import * as React from "react";
import { usePrevious } from "./primitive-utils";

type Props = Omit<React.ComponentProps<"input">, "checked"> & {
  checked: boolean | "indeterminate";
  /** Let the synthetic click bubble to ancestors such as a form `onChange`. */
  bubbles?: boolean;
};

export function FormInput({ checked, bubbles = true, style, ...props }: Props) {
  const ref = React.useRef<HTMLInputElement>(null);
  const previous = usePrevious(checked);
  React.useEffect(() => {
    const input = ref.current;
    const set = Object.getOwnPropertyDescriptor(
      window.HTMLInputElement.prototype,
      "checked",
    )?.set;
    if (input && set && previous !== checked) {
      input.indeterminate = checked === "indeterminate";
      set.call(input, checked === "indeterminate" ? false : checked);
      input.dispatchEvent(new Event("click", { bubbles }));
    }
  }, [previous, checked, bubbles]);
  const initial = React.useRef(checked === "indeterminate" ? false : checked);
  return (
    <input
      type="checkbox"
      aria-hidden
      defaultChecked={initial.current}
      {...props}
      tabIndex={-1}
      ref={ref}
      style={{
        ...style,
        position: "absolute",
        pointerEvents: "none",
        opacity: 0,
        margin: 0,
        transform: "translateX(-100%)",
      }}
    />
  );
}

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

"use client";
import { useState } from "react";
/** An optional owner, not a mandatory store or application provider. */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (next: T) => void] {
  const [local, setLocal] = useState(defaultValue),
    current = value === undefined ? local : value;
  return [
    current,
    (next) => {
      if (Object.is(current, next)) return;
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ];
}

@import "./ui-base.css";
.roc-ui[data-slot="switch"] {
  display: inline-flex;
  position: relative;
  align-items: center;
  flex-shrink: 0;
  width: 38px;
  height: 22px;
  padding: 3px;
  border: 0;
  border-radius: 99px;
  cursor: pointer;
  background: var(--roc-line, #dedede);
  transition: background-color var(--roc-motion-quick) ease-out;
}
.roc-ui[data-slot="switch"]::before {
  content: "";
  position: absolute;
  inset: -7px;
}
.roc-ui[data-slot="switch"][data-state="checked"] {
  background: var(--roc-ink, #252525);
}
.roc-ui[data-slot="switch-thumb"] {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: white;
  box-shadow: 0 1px 2px #0002;
  /* A transition, not a keyframe: the overshoot ease keeps reversals continuous. */
  transition: transform var(--roc-motion-medium) var(--roc-motion-bounce);
}
.roc-ui[data-slot="switch-thumb"][data-state="checked"] {
  transform: translateX(16px);
}
.roc-ui[data-slot="switch"][data-size="sm"] {
  width: 30px;
  height: 18px;
  padding: 3px;
}
.roc-ui[data-slot="switch"][data-size="sm"] .roc-ui[data-slot="switch-thumb"] {
  width: 12px;
  height: 12px;
}
.roc-ui[data-slot="switch"][data-size="sm"] [data-state="checked"] {
  transform: translateX(12px);
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
